	"github.com/lima-vm/lima/v2/pkg/registry"
)

func ResolveVMType(ctx context.Context, y *limatype.LimaYAML, filePath string) error {
	if y.VMType != nil && *y.VMType != "" {
		if err := validateConfigAgainstDriver(ctx, y, filePath, *y.VMType); err != nil {
			return err
		}
		logrus.Debugf("Using specified vmType %q for %q", *y.VMType, filePath)
		return nil
	}

	// If VMType is not specified, we go with the default platform driver.
	vmType := limatype.DefaultDriver()
	return validateConfigAgainstDriver(ctx, y, filePath, vmType)
}

func validateConfigAgainstDriver(ctx context.Context, y *limatype.LimaYAML, filePath, vmType string) error {
	extDriver, intDriver, exists := registry.Get(vmType)
	if !exists {
		return fmt.Errorf("vmType %q is not a registered driver", vmType)
	}

	if extDriver != nil {
		return handlePreConfiguredDriverAction(ctx, y, extDriver.Path, filePath)
	}

	if err := intDriver.AcceptConfig(y, filePath); err != nil {
		return err
	}
	if err := intDriver.FillConfig(y, filePath); err != nil {
		return err
	}

	return nil
}

func handlePreConfiguredDriverAction(ctx context.Context, y *limatype.LimaYAML, extDriverPath, filePath string) error {
	cmd := exec.CommandContext(ctx, extDriverPath, "--pre-driver-action")

	var stderrBuf bytes.Buffer
	cmd.Stderr = &stderrBuf

	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return fmt.Errorf("failed to get stdout pipe: %w", err)
	}
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return fmt.Errorf("failed to get stdin pipe: %w", err)
	}
	if err := cmd.Start(); err != nil {
		return fmt.Errorf("failed to start external driver: %w", err)
	}

	encoder := json.NewEncoder(stdin)
	if err := encoder.Encode(limatype.PreConfiguredDriverPayload{
		Config:   *y,
		FilePath: filePath,
	}); err != nil {
		stdin.Close()
		return fmt.Errorf("failed to encode pre-configured driver payload: %w", err)
	}
	stdin.Close()

	decoder := json.NewDecoder(stdout)
	var res limatype.LimaYAML
	if err := decoder.Decode(&res); err != nil {
		return fmt.Errorf("failed to decode pre-configured driver response: %w", err)
	}

	if err := cmd.Wait(); err != nil {
		if stderrBuf.Len() > 0 {
			return fmt.Errorf("pre-configured driver command failed: %w; stderr: %s", err, stderrBuf.String())
		}
		return fmt.Errorf("pre-configured driver command failed: %w", err)
	}

	if stderrBuf.Len() > 0 {
		return fmt.Errorf("external driver stderr: %s", stderrBuf.String())
	}

	*y = res
	logrus.Debugf("Pre-configured driver action completed successfully for %q", extDriverPath)
	return nil
}

func InspectStatus(ctx context.Context, inst *limatype.Instance) (string, error) {
	if inst == nil || inst.Config == nil || inst.Config.VMType == nil {
		return "", errors.New("instance or its configuration is not properly initialized")
	}

	extDriver, intDriver, exists := registry.Get(*inst.Config.VMType)
	if !exists {
		return "", fmt.Errorf("unknown or unsupported VM type: %s", *inst.Config.VMType)
	}

	if extDriver != nil {
		status, err := handleInspectStatusAction(ctx, inst, extDriver.Path)
		if err != nil {
			extDriver.Logger.Errorf("Failed to inspect status for instance %q: %v", inst.Name, err)
			return "", err
		}
		extDriver.Logger.Debugf("Instance %q inspected successfully with status: %s", inst.Name, inst.Status)
	//nolint:staticcheck // Warning about both top-level and vmOpts.vz.Rosetta being set
	if (cfg.VMOpts.VZ.Rosetta.Enabled != nil && cfg.VMOpts.VZ.Rosetta.BinFmt != nil) && (!isEmpty(cfg.Rosetta)) {
		logrus.Warn("Both top-level 'rosetta' and 'vmOpts.vz.rosetta' are configured. Using vmOpts.vz.rosetta. Top-level 'rosetta' is deprecated.")
	}

	if cfg.VMOpts.VZ.Rosetta.Enabled == nil {
		cfg.VMOpts.VZ.Rosetta.Enabled = ptr.Of(false)
	}
	if cfg.VMOpts.VZ.Rosetta.BinFmt == nil {
		cfg.VMOpts.VZ.Rosetta.BinFmt = ptr.Of(false)
	}

	return nil
}

func isEmpty(r limatype.Rosetta) bool {
	return r.Enabled == nil && r.BinFmt == nil
}

//go:embed boot/*.sh
var bootFS embed.FS

func (l *LimaVzDriver) BootScripts() (map[string][]byte, error) {
	scripts := make(map[string][]byte)

	entries, err := bootFS.ReadDir("boot")
	if err == nil {
		for _, entry := range entries {
			if entry.IsDir() {
				continue
			}

			content, err := bootFS.ReadFile("boot/" + entry.Name())
			if err != nil {
				return nil, err
			}

			scripts[entry.Name()] = content
		}
	}

	return scripts, nil
}

func (l *LimaVzDriver) AcceptConfig(cfg *limatype.LimaYAML, filePath string) error {
	if dir, basename := filepath.Split(filePath); dir != "" && basename == filenames.LimaYAML && limayaml.IsExistingInstanceDir(dir) {
		vzIdentifier := filepath.Join(dir, filenames.VzIdentifier) // since Lima v0.14
		if _, err := os.Lstat(vzIdentifier); !errors.Is(err, os.ErrNotExist) {
			logrus.Debugf("ResolveVMType: resolved VMType %q (existing instance, with %q)", "vz", vzIdentifier)
		}
	}

	for i, nw := range cfg.Networks {
		field := fmt.Sprintf("networks[%d]", i)
		switch {
		case nw.Lima != "":
			if nw.VZNAT != nil && *nw.VZNAT {
				return fmt.Errorf("field `%s.lima` and field `%s.vzNAT` are mutually exclusive", field, field)
			}
		case nw.Socket != "":
			if nw.VZNAT != nil && *nw.VZNAT {
				return fmt.Errorf("field `%s.socket` and field `%s.vzNAT` are mutually exclusive", field, field)
			}
		case nw.VZNAT != nil && *nw.VZNAT:
			if nw.Lima != "" {
				return fmt.Errorf("field `%s.vzNAT` and field `%s.lima` are mutually exclusive", field, field)
			}
			if nw.Socket != "" {
				return fmt.Errorf("field `%s.vzNAT` and field `%s.socket` are mutually exclusive", field, field)
			}
		}
	}

	if l.Instance == nil {
		l.Instance = &limatype.Instance{}
	}
	l.Instance.Config = cfg

	if err := l.Validate(context.Background()); err != nil {
		return fmt.Errorf("config not supported by the VZ driver: %w", err)
	}

	return nil
}

func (l *LimaVzDriver) Validate(_ context.Context) error {
	macOSProductVersion, err := osutil.ProductVersion()
	if err != nil {
		return err
	}
	if macOSProductVersion.LessThan(*semver.New("13.0.0")) {
		return errors.New("VZ driver requires macOS 13 or higher to run")
	}
	if runtime.GOARCH == "amd64" && macOSProductVersion.LessThan(*semver.New("15.5.0")) {
		logrus.Warnf("vmType %s: On Intel Mac, macOS 15.5 or later is required to run Linux 6.12 or later. "+
			"Update macOS, or change vmType to \"qemu\" if the VM does not start up. (https://github.com/lima-vm/lima/issues/3334)",
			*l.Instance.Config.VMType)
	}
	if l.Instance.Config.MountType != nil && *l.Instance.Config.MountType == limatype.NINEP {
		return fmt.Errorf("field `mountType` must be %q or %q for VZ driver , got %q", limatype.REVSSHFS, limatype.VIRTIOFS, *l.Instance.Config.MountType)
	}
	if *l.Instance.Config.Firmware.LegacyBIOS {
		logrus.Warnf("vmType %s: ignoring `firmware.legacyBIOS`", *l.Instance.Config.VMType)
	}
	for _, f := range l.Instance.Config.Firmware.Images {
		switch f.VMType {
		case "", limatype.VZ:
			if f.Arch == *l.Instance.Config.Arch {
				return errors.New("`firmware.images` configuration is not supported for VZ driver")
			}
		}
	}
	if unknown := reflectutil.UnknownNonEmptyFields(l.Instance.Config, knownYamlProperties...); l.Instance.Config.VMType != nil && len(unknown) > 0 {
		logrus.Warnf("vmType %s: ignoring %+v", *l.Instance.Config.VMType, unknown)
	}

	if !limayaml.IsNativeArch(*l.Instance.Config.Arch) {
		return fmt.Errorf("unsupported arch: %q", *l.Instance.Config.Arch)
	}

	for i, image := range l.Instance.Config.Images {
		if unknown := reflectutil.UnknownNonEmptyFields(image, "File", "Kernel", "Initrd"); len(unknown) > 0 {
			logrus.Warnf("vmType %s: ignoring images[%d]: %+v", *l.Instance.Config.VMType, i, unknown)
		}
	}

	for i, mount := range l.Instance.Config.Mounts {
		if unknown := reflectutil.UnknownNonEmptyFields(mount, "Location",
			"MountPoint",
			"Writable",
			"SSHFS",
			"NineP",
		); len(unknown) > 0 {
			logrus.Warnf("vmType %s: ignoring mounts[%d]: %+v", *l.Instance.Config.VMType, i, unknown)
		}
	}

	for i, network := range l.Instance.Config.Networks {
		if unknown := reflectutil.UnknownNonEmptyFields(network, "VZNAT",
			"Lima",
			"Socket",
			return fmt.Errorf("field `param` key %q is not used in any provision, probe, copyToHost, or portForward", key)
		}
	}
	return nil
}

func validatePort(field string, port int) error {
	switch {
	case port < 0:
		return fmt.Errorf("field `%s` must be > 0", field)
	case port == 0:
		return fmt.Errorf("field `%s` must be set", field)
	case port == 22:
		return fmt.Errorf("field `%s` must not be 22", field)
	case port > 65535:
		return fmt.Errorf("field `%s` must be < 65536", field)
	}
	return nil
}

func warnExperimental(y *limatype.LimaYAML) {
	if *y.MountType == limatype.VIRTIOFS && runtime.GOOS == "linux" {
		logrus.Warn("`mountType: virtiofs` on Linux is experimental")
	}
	switch *y.Arch {
	case limatype.RISCV64, limatype.ARMV7L, limatype.S390X, limatype.PPC64LE:
		logrus.Warnf("`arch: %s ` is experimental", *y.Arch)
	}
	if y.Video.Display != nil && strings.Contains(*y.Video.Display, "vnc") {
		logrus.Warn("`video.display: vnc` is experimental")
	}
	if y.Audio.Device != nil && *y.Audio.Device != "" {
		logrus.Warn("`audio.device` is experimental")
	}
	if y.MountInotify != nil && *y.MountInotify {
		logrus.Warn("`mountInotify` is experimental")
	}
}

// ValidateAgainstLatestConfig validates the values between the latest YAML and the updated(New) YAML.
// This validates configuration rules that disallow certain changes, such as shrinking the disk.
func ValidateAgainstLatestConfig(ctx context.Context, yNew, yLatest []byte) error {
	var n limatype.LimaYAML
	var errs error

	// Load the latest YAML and fill in defaults
	l, err := LoadWithWarnings(ctx, yLatest, "")
	if err != nil {
		errs = errors.Join(errs, err)
	}
	if err := driverutil.ResolveVMType(ctx, l, ""); err != nil {
		errs = errors.Join(errs, fmt.Errorf("failed to resolve vm for %q: %w", "", err))
	}
	if err := Unmarshal(yNew, &n, "Unmarshal new YAML bytes"); err != nil {
		errs = errors.Join(errs, err)
	}

	// Handle editing the template without a disk value
	if n.Disk == nil || l.Disk == nil {
		return errs
	}

	// Disk value must be provided, as it is required when creating an instance.
	nDisk, err := units.RAMInBytes(*n.Disk)
	if err != nil {
		errs = errors.Join(errs, err)
	}
	lDisk, err := units.RAMInBytes(*l.Disk)
	if err != nil {
		errs = errors.Join(errs, err)
	}

	// Reject shrinking disk
	if nDisk < lDisk {
		errs = errors.Join(errs, fmt.Errorf("field `disk`: shrinking the disk (%v --> %v) is not supported", *l.Disk, *n.Disk))
	}

	return errs
}

